1	// Acceptance tests for the change request:
2	//   "Let me tuck away clients I no longer work with. They should drop off my list and my search.
3	//    I do not want to lose them. Note it when I do."
4	//
5	// ARCHIVING a client is a soft hide, NOT a delete — nothing is lost. Each client in the list offers
6	// a control to archive it (client-archive-<id>). Archiving a client:
7	//   - drops it off the clients list (clients-page), leaving its siblings untouched;
8	//   - drops it off the client SEARCH too — a search by its name no longer finds it;
9	//   - loses NOTHING — the client is still there (its own detail page, reached by URL, still renders
10	//     the client with its projects intact);
11	//   - appends exactly one audit record — CLIENT_ARCHIVED id=<id> — so the act is noted (the list
12	//     only stops showing the client; it cannot show that it was archived).
13	//
14	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
15	// (auditLines()). Data is arranged via resetAndSeed; the archive is driven through the UI. Seed
16	// honours clients: { id, name, email, archived } — `archived` places a client directly in the
17	// tucked-away state so the hiding can be checked without a click, and projects: { id, clientId,
18	// name } so the client's retained data can be confirmed.
19	//
20	// This SHOULD FAIL before the change: today a client row has no archive control and nothing is
21	// recorded when a client is tucked away.
22	import { test, expect } from '@playwright/test';
23	import { resetAndSeed } from '../support/seed';
24	import { auditLines } from '../support/audit';
25	
