27	  test('archiving drops a client off the list, keeps a record, and loses nothing', async ({ page }) => {
28	    await resetAndSeed({
29	      clients: [
30	        { id: 1, name: 'Acme Corp', email: 'ops@acme.example' },
31	        { id: 2, name: 'Globex', email: 'hello@globex.example' },
32	      ],
33	      // The archived client keeps its data: a project under it must still be reachable afterwards.
34	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
35	    });
36	
37	    await page.goto('/clients');
38	    await expect(page.getByTestId('clients-page')).toBeVisible();
39	
40	    const first = page.getByTestId('client-row-1');
41	    const second = page.getByTestId('client-row-2');
42	    await expect(first).toBeVisible();
43	    await expect(second).toBeVisible();
44	
45	    // reset cleared the audit file — nothing has been archived yet.
46	    expect(auditLines()).toEqual([]);
47	
48	    // Tuck the first client away.
49	    await page.getByTestId('client-archive-1').click();
50	
51	    // It drops off the list; its sibling is untouched.
52	    await expect(first).toHaveCount(0);
53	    await expect(second).toBeVisible();
54	    await expect(second.getByTestId('client-name')).toHaveText('Globex');
55	
56	    // Exactly one record was kept, naming the archived client.
57	    await expect.poll(() => auditLines()).toEqual(['CLIENT_ARCHIVED id=1']);
58	
59	    // Nothing was lost: the client still exists. Its own detail page, reached by URL, still renders
60	    // the client with its project intact.
61	    await page.goto('/clients/1');
62	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
63	    await expect(page.getByTestId('client-projects-table')).toBeVisible();
64	    await expect(page.getByTestId('project-row-1')).toBeVisible();
