66	
67	    // Reaching the detail page is a read — it does not record anything new.
68	    await expect.poll(() => auditLines()).toEqual(['CLIENT_ARCHIVED id=1']);
69	  });
70	
71	  test('an already-archived client is absent from the list and cannot be found by search', async ({ page }) => {
72	    await resetAndSeed({
