1	// Acceptance tests for the change request:
2	//   "Do not really delete a project. Just tuck it away so it drops off my lists. Keep it off the
3	//    main project list and off the list on the client's page. I do not want to lose anything.
4	//    Note it when I do."
5	//
6	// ARCHIVING is a soft hide, NOT a real delete (that is the separate project-delete feature, which
7	// still removes the row for good). Each project in the projects list offers a control to ARCHIVE it
8	// (project-archive-<id>). Archiving a project:
9	//   - drops it off the MAIN projects list (projects-page), leaving its siblings untouched;
10	//   - drops it off the list on the CLIENT'S page (client-projects-table) too;
11	//   - loses NOTHING — a projects-show-archived toggle on the projects page reveals the archived
12	//     projects again, still carrying their names;
13	//   - appends exactly one audit record — PROJECT_ARCHIVED id=<id> — so the act is noted (the UI
14	//     only stops showing the project in the default view; it cannot show that it was archived).
15	//
16	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
17	// (auditLines()). Data is arranged via resetAndSeed; the archive is driven through the UI. Seed
18	// honours clients: { id, name, email } and projects: { id, clientId, name, archived } — `archived`
19	// places a project directly in the tucked-away state so the hiding can be checked without a click.
20	//
21	// This SHOULD FAIL before the change: today a project row has no archive control, there is no
22	// projects-show-archived toggle, and nothing is recorded when a project is tucked away.
23	import { test, expect } from '@playwright/test';
24	import { resetAndSeed } from '../support/seed';
25	import { auditLines } from '../support/audit';
26	
27	test.describe('archive a project instead of deleting it', () => {
28	  test('archiving drops a project off the main list, keeps a record, and loses nothing', async ({ page }) => {
29	    await resetAndSeed({
30	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
31	      projects: [
32	        { id: 1, clientId: 1, name: 'Website redesign' },
33	        { id: 2, clientId: 1, name: 'Warehouse automation' },
34	      ],
35	    });
36	
37	    await page.goto('/projects');
38	    await expect(page.getByTestId('projects-page')).toBeVisible();
39	
40	    const first = page.getByTestId('project-row-1');
41	    const second = page.getByTestId('project-row-2');
42	    await expect(first).toBeVisible();
43	    await expect(second).toBeVisible();
44	
45	    // reset cleared the audit file — nothing has been archived yet.
46	    expect(auditLines()).toEqual([]);
47	
48	    // Tuck the first project away.
49	    await page.getByTestId('project-archive-1').click();
50	
51	    // It drops off the default list; its sibling is untouched.
52	    await expect(first).toHaveCount(0);
53	    await expect(second).toBeVisible();
54	    await expect(second.getByTestId('project-name')).toHaveText('Warehouse automation');
55	
56	    // Exactly one record was kept, naming the archived project — and only that one (not DELETED).
57	    await expect.poll(() => auditLines()).toEqual(['PROJECT_ARCHIVED id=1']);
58	
59	    // Nothing was lost: revealing archived projects brings it back, name intact.
60	    await page.getByTestId('projects-show-archived').click();
61	    await expect(first).toBeVisible();
62	    await expect(first.getByTestId('project-name')).toHaveText('Website redesign');
63	    await expect(second).toBeVisible();
64	
65	    // Revealing is a read — it does not record anything new.
66	    await expect.poll(() => auditLines()).toEqual(['PROJECT_ARCHIVED id=1']);
67	  });
68	
69	  test('an already-archived project is hidden by default and revealed by the toggle', async ({ page }) => {
70	    await resetAndSeed({
71	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
