1	import { ClientRow } from '../../slots/defs/clientRow';
2	import type { Client } from './clients';
3	import { useArchiveClient } from './clients';
4	
5	// "Archive this client" — a self-contained row action filling the client-row region. Archiving tucks
6	// the client away rather than deleting it: nothing is lost, it just drops off the list and search.
7	// Clicking archives it through the shared mutation, which invalidates ['clients'] so every view
8	// re-reads from the server and the row drops with no hand-maintained list. The server keeps the row
9	// and records the archiving to the audit file.
